mapper.select:
SELECT schema_ref AS schemaRef, model_ref AS modelRef, output_mode AS outputMode, COUNT(*) AS total, COUNT(*) FILTER (WHERE outcome = 'VALID' AND COALESCE(repair_rounds, 0) = 0) AS firstPass, COUNT(*) FILTER (WHERE outcome IN ('VALID', 'VALID_WITH_UNKNOWN')) AS finalPass, COUNT(*) FILTER (WHERE outcome = 'VALID_WITH_UNKNOWN') AS fallback, COUNT(*) FILTER (WHERE outcome = 'HUMAN_PENDING') AS humanPending, COUNT(*) FILTER (WHERE outcome = 'FAILED') AS failed, COALESCE(AVG(repair_rounds), 0) AS avgRepairRounds FROM runtime_item WHERE type = 'data'
AND create_at >= #{from}
AND create_at < #{to}
GROUP BY schema_ref, model_ref, output_mode
